INSERT INTO `wp_postmeta` (`meta_id`, `post_id`, `meta_key`, `meta_value`) VALUES
(9672, 1175, 'мероприятия_4_мероприятие', 'Финансовый рынок России: что скрывается за \"очищением\" и структурными изменениями'),
